@Observable @MainActor
final class FeedViewModel {
    enum State { case idle, loading, loaded([Post]), failed(String) }
    private(set) var state: State = .idle
    private let api: FeedAPI                       // protocol, injected

    init(api: FeedAPI) { self.api = api }

    func refresh() async {
        state = .loading
        do { state = .loaded(try await api.feed()) }
        catch { state = .failed("Could not load feed") }
    }
}

struct FeedView: View {
    @State var model: FeedViewModel
    var body: some View {
        switch model.state {
        case .idle, .loading: ProgressView().task { await model.refresh() }
        case .loaded(let posts): List(posts) { Text($0.title) }
        case .failed(let message): Text(message)
        }
    }
}
